#include "stdlib/blas/ext/base/ndarray/dcartesian_product.h"
#include "stdlib/blas/ext/base/dcartesian_product.h"
#include "stdlib/ndarray/ctor.h"
#include "stdlib/blas/base/shared.h"

/**
* Computes the Cartesian product for two double-precision floating-point ndarrays.
*
* ## Notes
*
* -   The function expects two one-dimensional input ndarrays and a two-dimensional output ndarray.
* -   Pairs are stored as rows, with the first and second elements in the first and second columns.
*
* @param arrays    list containing ndarrays
*/
void stdlib_blas_ext_dcartesian_product( const struct ndarray *arrays[] ) {
	const struct ndarray *x = arrays[ 0 ];
	const struct ndarray *y = arrays[ 1 ];
	const struct ndarray *out = arrays[ 2 ];

	const CBLAS_INT M = stdlib_ndarray_dimension( x, 0 );
	const CBLAS_INT N = stdlib_ndarray_dimension( y, 0 );
	const CBLAS_INT strideX = stdlib_ndarray_stride_elements( x, 0 );
	const CBLAS_INT offsetX = stdlib_ndarray_offset_elements( x );
	const CBLAS_INT strideY = stdlib_ndarray_stride_elements( y, 0 );
	const CBLAS_INT offsetY = stdlib_ndarray_offset_elements( y );
	const CBLAS_INT strideOut1 = stdlib_ndarray_stride_elements( out, 0 );
	const CBLAS_INT strideOut2 = stdlib_ndarray_stride_elements( out, 1 );
	const CBLAS_INT offsetOut = stdlib_ndarray_offset_elements( out );

	const double *dataX = (const double *)stdlib_ndarray_data( x );
	const double *dataY = (const double *)stdlib_ndarray_data( y );
	double *dataOut = (double *)stdlib_ndarray_data( out );
	API_SUFFIX(stdlib_strided_dcartesian_product_ndarray)( M, N, dataX, strideX, offsetX, dataY, strideY, offsetY, dataOut, strideOut1, strideOut2, offsetOut );
}
